mapper.select:


     and A.type_id = #{brtCheckVo.typeId}
     and A.order_id = #{brtCheckVo.orderId}
     and A.order_no like concat('%',#{brtCheckVo.orderNo},'%')
     and A.user_id = #{brtCheckVo.userId}
     and A.check_amount = #{brtCheckVo.checkAmount}
     and A.account_id = #{brtCheckVo.accountId}
     and A.check_date = #{brtCheckVo.checkDate}
     and A.check_remark = #{brtCheckVo.checkRemark}
     and A.attachments = #{brtCheckVo.attachments}
     and A.check_type = #{brtCheckVo.checkType}



                and date_format(A.check_date,'%y%m%d') = date_format(now(),'%y%m%d')


                and DATE(A.check_date) = CURDATE() - INTERVAL 1 DAY


                and date_format(A.check_date,'%y%m') = date_format(now(),'%y%m')


                and QUARTER(A.check_date) = QUARTER(CURDATE()) and YEAR(A.check_date) = YEAR(CURDATE())


                and YEAR(A.check_date) = YEAR(CURDATE())




        and date_format(A.check_date,'%y%m%d') between date_format(#{brtCheckVo.checkDateStart},'%y%m%d') and date_format(#{brtCheckVo.checkDateEnd},'%y%m%d')


    ${brtCheckVo.params.brtDataScope}

order by A.create_time desc
